--------------------------------------------------------------------------------
                    --TABLA PARA ARCHIVOS_POLIZAS--
--------------------------------------------------------------------------------
DROP PUBLIC SYNONYM ARCHIVOS_POLIZAS;

CREATE TABLE SICAS_OC.ARCHIVOS_POLIZAS(
    "ID"                    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY 
                            MINVALUE 1 MAXVALUE 9999999999999999999999999999 
                            INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE 
                            NOT NULL ENABLE,                            -- Identificador único del archivo   
    "IDPOLIZA"              NUMBER(14,0) NOT NULL ENABLE,               -- Identificador de la póliza
    "CODEMPRESA"            NUMBER(14,0) DEFAULT 1 NOT NULL ENABLE,     -- Código de la empresa
    "CODCIA"                NUMBER(14,0) DEFAULT 1 NOT NULL ENABLE,     -- Código de la compañía
    "NOMBRE_ARCHIVO"        VARCHAR2(255) NOT NULL ENABLE,              -- Nombre del archivo
    "CLV_DOCUMENTO_GRUPO"   VARCHAR2(5) NOT NULL ENABLE,                -- Clave del grupo de documentos
    "CLV_DOCUMENTO"         VARCHAR2(5) DEFAULT 'OTRO',                 -- Clave del tipo de documento
    "COMENTARIOS"           VARCHAR2(4000),                             -- Comentarios del archivo
    "ESTATUS_BORRADO"       VARCHAR2(1) DEFAULT 'N' NOT NULL ENABLE,    -- Estatus lógico de borrado (N: no borrado, S: borrado)
    "ARCHIVO_BLOB"          BLOB NOT NULL ENABLE,                       -- Contenido binario del archivo
    "FILE_MIME_TYPE"        VARCHAR2(255),                              -- Tipo MIME del archivo (e.g., application/pdf)
    "FILE_CHARSET"          VARCHAR2(255),                              -- Juego de caracteres del archivo 
    "TAMANIO_BYTES"         NUMBER,                                     -- Tamaño del archivo en bytes
    "CREATED"               DATE DEFAULT SYSDATE NOT NULL ENABLE,             -- Fecha de creación del registro
    "CREATED_BY"            VARCHAR2(50) DEFAULT COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'), USER) NOT NULL ENABLE,    -- Usuario que creó el registro
    "UPDATED"               DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                           -- Fecha de última actualización del registro
    "UPDATED_BY"            VARCHAR2(50) DEFAULT COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'), USER) NOT NULL ENABLE,    -- Usuario que actualizó por última vez
    "DELETED"               DATE DEFAULT SYSDATE,                                                                           -- Fecha en que fue marcado como eliminado (borrado lógico)
    "DELETED_BY"            VARCHAR2(50) DEFAULT COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'), USER),                    -- Usuario que realizó el borrado lógico
    "BLOB_LAST_UPDATE"      DATE DEFAULT SYSDATE                                                                            -- Fecha de última actualización del archivo (BLOB)
) TABLESPACE TS_SICASOC;

--ÍNDICES
CREATE UNIQUE INDEX SICAS_OC.ARCHIVOS_POLIZAS_INDX ON SICAS_OC.ARCHIVOS_POLIZAS (ID,CODCIA,CODEMPRESA) TABLESPACE IDX_SICASOC;
/
--PRIMARY Y FOREIGN KEY
ALTER TABLE SICAS_OC.ARCHIVOS_POLIZAS ADD CONSTRAINT PK_ARCHIVOS_POLIZAS PRIMARY KEY (ID,CODCIA,CODEMPRESA) USING INDEX;
/

--GRANT
GRANT SELECT, INSERT, UPDATE, DELETE, ALTER ON SICAS_OC.ARCHIVOS_POLIZAS TO ROL_MODIFICA_SICAS;
GRANT SELECT ON SICAS_OC.ARCHIVOS_POLIZAS TO ROL_CONSULTA_SICAS;
/

--SINÓNIMO
CREATE OR REPLACE PUBLIC SYNONYM ARCHIVOS_POLIZAS FOR SICAS_OC.ARCHIVOS_POLIZAS;
/


--COMENTARIOS DESCRIPTIVOS
COMMENT ON TABLE SICAS_OC.ARCHIVOS_POLIZAS                             IS 'Tabla que almacena archivos asociados a pólizas, clasificacion de documento y control de borrado lógico';

COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.ID                         IS 'Identificador único del archivo';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.IDPOLIZA                   IS 'Identificador de la póliza asociada';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.CODEMPRESA                 IS 'Código de la empresa';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.CODCIA                     IS 'Código CODCIA';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.NOMBRE_ARCHIVO             IS 'Nombre del archivo cargado';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.CLV_DOCUMENTO_GRUPO        IS 'Clave del grupo de documentos';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.CLV_DOCUMENTO              IS 'Clave del tipo de documento';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.COMENTARIOS                IS 'Comentarios adicionales sobre el archivo';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.ESTATUS_BORRADO            IS 'Estatus lógico de borrado (N: no borrado, S: borrado)';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.ARCHIVO_BLOB               IS 'Contenido binario del archivo';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.FILE_MIME_TYPE             IS 'Tipo MIME del archivo (ej. application/pdf)';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.FILE_CHARSET               IS 'Juego de caracteres del archivo';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.TAMANIO_BYTES              IS 'Tamaño del archivo en bytes';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.CREATED                    IS 'Fecha de creación del registro';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.CREATED_BY                 IS 'Usuario que creó el registro';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.UPDATED                    IS 'Fecha de última actualización del registro';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.UPDATED_BY                 IS 'Usuario que actualizó por última vez el registro';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.DELETED                    IS 'Fecha en la que el archivo fue marcado como eliminado';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.DELETED_BY                 IS 'Usuario que realizó el borrado lógico';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS.BLOB_LAST_UPDATE           IS 'Fecha de última actualización del contenido del archivo (BLOB)';